const APPCAST_URL = "https://raw.githubusercontent.com/oiwdis/map-lock/main/appcast.xml";
const RELEASE_URL = "https://api.github.com/repos/oiwdis/map-lock/releases/latest";
const VERSION_RE = /^\d+\.\d+\.\d+$/;
const FALLBACK_VERSION = "1.3.3";
const FRESH_TTL = 600;

function versionFromAppcast(xml) {
  const match = String(xml).match(/<sparkle:shortVersionString>\s*([^<]+?)\s*<\/sparkle:shortVersionString>/);
  if (!match || !VERSION_RE.test(match[1])) return null;
  return match[1];
}

function versionFromRelease(payload) {
  const tag = payload && payload.tag_name;
  if (typeof tag !== "string") return null;
  const version = tag.replace(/^v/, "");
  return VERSION_RE.test(version) ? version : null;
}
const FRESH_KEY = "https://map-lock-site.cache/version/fresh";
const LAST_KEY = "https://map-lock-site.cache/version/last";
let memoryVersion = null;

async function readVersionCache(key) {
  try {
    const hit = await caches.default.match(key);
    if (!hit) return null;
    const text = (await hit.text()).trim();
    return VERSION_RE.test(text) ? text : null;
  } catch (e) {
    return null;
  }
}

async function writeVersionCache(key, value, ttl) {
  try {
    await caches.default.put(key, new Response(value, {
      headers: { "Cache-Control": "public, max-age=" + ttl, "Content-Type": "text/plain; charset=utf-8" },
    }));
  } catch (e) {}
}

